begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select no_plan();
create temp table byte_fixture(snapshot jsonb,document jsonb,bytes bytea);
insert into byte_fixture values(jsonb_build_object('schema_version',5,'lab_reports',jsonb_build_array(jsonb_build_object('id','b5000000-0000-4000-8000-000000000001','document_id','b5000000-0000-4000-8000-000000000002','document_version',1,'mime_type','application/pdf','file_size',9,'receipt_id','b5000000-0000-4000-8000-000000000003','receipt_hash',repeat('a',64),'capture_hash',repeat('b',64),'content_sha256',encode(sha256(convert_to('%PDF-test','UTF8')),'hex'))),'external_records','[]'::jsonb),jsonb_build_object('id','b5000000-0000-4000-8000-000000000002','version',1,'mime_type','application/pdf','file_size',9,'content_sha256',encode(sha256(convert_to('%PDF-test','UTF8')),'hex'),'provenance_captures',jsonb_build_array(jsonb_build_object('family','lab_report','version_id','b5000000-0000-4000-8000-000000000001','receipt_id','b5000000-0000-4000-8000-000000000003','receipt_hash',repeat('a',64),'capture_hash',repeat('b',64)))),convert_to('%PDF-test','UTF8'));
select lives_ok($$select verify_release_source_original_v5(snapshot,document,bytes) from byte_fixture$$,'Exact captured original accepted');
select throws_ok($$select verify_release_source_original_v5(snapshot,document,convert_to('%PDF-best','UTF8')) from byte_fixture$$,'23514',null,'Same-length valid-signature changed bytes rejected');
select throws_ok($$select verify_release_source_original_v5(snapshot,document-'content_sha256',bytes) from byte_fixture$$,'23514',null,'Missing digest cannot downgrade selected source');
select throws_ok($$select verify_release_source_original_v5(snapshot,document-'provenance_captures',bytes) from byte_fixture$$,'23514',null,'Missing capture proof rejected');
select throws_ok($$select verify_release_source_original_v5(snapshot,jsonb_set(document,'{version}','2'),bytes) from byte_fixture$$,'23514',null,'Different document version rejected');
select throws_ok($$select verify_release_source_original_v5(snapshot,jsonb_set(document,'{provenance_captures,0,capture_hash}',to_jsonb(repeat('c',64))),bytes) from byte_fixture$$,'23514',null,'Capture substitution rejected');
select throws_ok($$select verify_release_source_original_v5(snapshot-'lab_reports',document,bytes) from byte_fixture$$,'23514',null,'Missing selected source family rejected');
select throws_ok($$select verify_release_source_original_v5(jsonb_set(snapshot,'{lab_reports}','[]'),document,bytes) from byte_fixture$$,'23514',null,'Unselected proof cannot become ordinary original');
select lives_ok($$select verify_release_source_original_v5(jsonb_set(snapshot,'{lab_reports}','[]'),document-array['content_sha256','provenance_captures'],bytes) from byte_fixture$$,'Ordinary schema5 metadata retains separate unverified contract');
select lives_ok($$select verify_release_source_original_v5(jsonb_build_object('schema_version',v),document,convert_to('%PDF-best','UTF8')) from byte_fixture cross join generate_series(1,4) v$$,'Earlier schemas retain original capture contract');
select ok(not has_function_privilege('authenticated','public.verify_release_source_original_v5(jsonb,jsonb,bytea)','execute'),'Staff cannot invoke private verifier');
select ok(not has_function_privilege('service_role','public.verify_release_source_original_v5(jsonb,jsonb,bytea)','execute'),'Service cannot invoke private verifier separately');
select ok(has_function_privilege('service_role','public.capture_release_email_payload(uuid,uuid,text)','execute'),'Email capture service contract preserved');
select ok(has_function_privilege('service_role','public.capture_document_link(uuid,uuid,text,text,text)','execute'),'Document capture service contract preserved');
select * from finish();rollback;
